effect.shader:
vec3 u_xlat0;
vec3 u_xlat1;
bool u_xlatb6;
void main()
{
    u_xlat0.xyz = _fill_color.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat0.xyz = _fill_color.xyz * u_xlat0.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat0.xyz = u_xlat0.xyz * _fill_color.xyz;
    u_xlat1.xyz = texture(inputImg, acScreenNorm.xy).xyz;
    u_xlatb6 = 0<int(_hasRT);
    fragColor.xyz = (bool(u_xlatb6)) ? u_xlat1.xyz : u_xlat0.xyz;
    u_xlat0.x = 1.0;
    fragColor.w = (u_xlatb6) ? u_xlat0.x : _fill_color.w;
    return;
}
